-- Errata reading for O19: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream='encounters'), seen AS (SELECT DISTINCT patient FROM r WHERE json_extract(payload,'$.organization_id') LIKE 'WH-PRACTICE-%' AND json_extract(payload,'$.type') IN ('primary_care','office','pediatric_office') AND json_extract(payload,'$.event_date') BETWEEN '2028-08-16' AND '2029-08-15') SELECT COUNT(*) AS count FROM patients p WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported'))>=18 AND p.id NOT IN (SELECT patient FROM seen);
